import { atom, read, update } from 'claude-code'
import type { EngineInterface as Engine, Register } from 'claude-code'

import type { Banner, Last, Snap, Todo } from '../types'
import { EXTRAS, mainColor, SPRITES, type Grid } from './sprites'
import { BAND_MS, bandGrid } from './band'
import { bubble, escapeAt, partner, scene, SPRITE_W, type Force, type FxKind, type Scene } from './stage'
import { cheer, encLine, escape, say } from './talk'
import { cells, merge, paint, stamp, STAGE_ROWS, type Weather } from './world'

const PANE = 'sidebar'
const snap = atom({ plugin: 'pixel-sidebar', key: 'snap' } as const, {
  model: '', pct: 0, tokens: 0, window: 0, usd: 0, agents: [], startedAt: 0, ponytail: '',
} as Snap)
const tick = atom({ plugin: 'pixel-sidebar', key: 'tick' } as const, 0)
const last = atom({ plugin: 'pixel-sidebar', key: 'last' } as const, { tool: '', file: '' } as Last)
const todos = atom({ plugin: 'pixel-sidebar', key: 'todos' } as const, [] as Todo[])
const weather = atom({ plugin: 'pixel-sidebar', key: 'weather' } as const, { temp: null, desc: '', at: 0 } as Weather)
const banner = atom({ plugin: 'pixel-sidebar', key: 'banner' } as const, { kind: '', at: -99 } as Banner)
const force = atom({ plugin: 'pixel-sidebar', key: 'force' } as const, { at: -999, idx: 0 } as Force)
const gen = atom({ plugin: 'pixel-sidebar', key: 'gen' } as const, '')
const NAMES = SPRITES.map(s => s.name)
const lines = new Map<string, string>() // fala fixa por janela (turno:tipo)
let room = 34 // largura do palco, lida no último render
let coins = 0
let band: { kind: FxKind; start: number; power?: number } | null = null // especial atravessando a tela
const began = new Map<string, number>() // quando cada tarefa entrou em andamento (especial carregada)
let chargeMs = 5 * 60_000
let notifs = true
let alertUsd = 10
let home = ''
// progresso salvo em ~/.claude/pixel-sidebar.json
const stats = { xp: 0, tasks: 0, deaths: 0, bosses: 0, focus: 0, got: [] as string[] }
const ACH: [string, string, () => boolean][] = [
  ['Primeira vitória', '1ª tarefa concluída', () => stats.tasks >= 1],
  ['Produtivo', '10 tarefas concluídas', () => stats.tasks >= 10],
  ['Lenda', '100 tarefas concluídas', () => stats.tasks >= 100],
  ['Caçador de bugs', 'derrotou um chefão', () => stats.bosses >= 1],
  ['Fênix', 'morreu 3 vezes e voltou', () => stats.deaths >= 3],
  ['Foco total', 'completou um pomodoro', () => stats.focus >= 1],
]
const level = (xp: number) => Math.floor(Math.sqrt(xp / 25)) + 1
const BOSSES = ['Bug Gigante', 'Null Pointer', 'Segfault', 'Merge Conflict', 'Stack Overflow']
let boss = { streak: 0, name: '' } // erros seguidos no Bash; 3+ = chefão na tela
let pomo: { end: number; min: number } | null = null
const warned = new Set<string>()
let costStep = -1
const byName = (name: string) => [...SPRITES, ...EXTRAS].find(s => s.name === name)
const flipped = (g: Grid, flip: boolean) => (flip ? g.map(row => [...row].reverse()) : g)

const bar = (pct: number, w = 18) => {
  const n = Math.round((Math.min(100, pct) / 100) * w)
  return '█'.repeat(n) + '░'.repeat(w - n)
}
const k = (n: number) => (n >= 1000 ? `${(n / 1000).toFixed(1)}k` : `${n}`)
const mins = (ms: number) => `${Math.floor(ms / 60000)}min`
const SEED = Math.floor(Math.random() * 1000) // ponytail: novo a cada load, ordem dos personagens varia por sessão

const save = ($: Engine) => $.fs.write(`${home}/.claude/pixel-sidebar.json`, JSON.stringify(stats)).catch(() => {})

/** Dá XP, soma o contador e avisa nível novo e conquistas. */
async function gain($: Engine, xp: number, field?: 'tasks' | 'deaths' | 'bosses' | 'focus') {
  const before = level(stats.xp)
  stats.xp += xp
  if (field) stats[field]++
  if (level(stats.xp) > before) $.ui.toast(`LEVEL UP! Nível ${level(stats.xp)}`, { timeoutMs: 5000 })
  for (const [name, why, ok] of ACH) {
    if (stats.got.includes(name) || !ok()) continue
    stats.got.push(name)
    $.ui.toast(`Conquista: ${name} (${why})`, { timeoutMs: 6000 })
  }
  await save($)
}

const ping = ($: Engine, text: string) => { if (notifs) void $.ui.notify(text).catch(() => {}) }

/** O personagem do palco reage: fala a linha e solta a especial (no máximo uma a cada ~15s). */
async function react($: Engine, why: 'done' | 'ask' | 'pause' | 'abort', detail: string, power?: number, custom?: string) {
  try { await reactNow($, why, detail, power, custom) } catch { /* enfeite: nunca atrapalha o trabalho */ }
}

async function reactNow($: Engine, why: 'done' | 'ask' | 'pause' | 'abort', detail: string, power?: number, custom?: string) {
  const n = await read($, tick)
  const f = await read($, force)
  if (n - f.at < 22) return
  const idx = scene(n, SEED, NAMES, room, f).idx
  const line = custom ?? cheer(why, NAMES[idx]!, detail, n)
  lines.set(`f${n}:shout`, power ? `CARREGADO! ${line}` : line)
  await update($, force, () => ({ at: n, idx, power }))
}

export const register: Register = (on, options) => {
  chargeMs = Number(options?.carregado_min ?? 5) * 60_000
  notifs = options?.notificacoes !== false
  alertUsd = Number(options?.custo_alerta_usd ?? 10)
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'sidebar', description: 'Abre a barra lateral' })
    await $.command.register({
      name: 'especial',
      description: 'Faz o personagem da barra lateral soltar a especial agora',
      argumentHint: '[nome do personagem] [forte]',
    })
    await $.command.register({
      name: 'encontro',
      description: 'Chama dois personagens pro palco ao mesmo tempo',
      argumentHint: '[mario|sonic|ryu|guile|scorpion|sub-zero|pac-man]',
    })
    await $.command.register({
      name: 'pomodoro',
      description: 'Contagem de foco com o personagem (padrão 25 min; "parar" cancela)',
      argumentHint: '[minutos|parar]',
    })
    home = (await $.env.get('HOME')) ?? ''
    Object.assign(stats, JSON.parse(await $.fs.read(`${home}/.claude/pixel-sidebar.json`).catch(() => '{}')))
    const r = await $.ui.open({ id: PANE, title: 'Sessão', columns: 34 })
    if (!r.isPlaced) $.ui.toast('pixel-sidebar: terminal estreito, rode /sidebar ou alargue a janela', { timeoutMs: 8000 })
    // hot reload roda session.start de novo: cada geração cancela os timers da anterior
    const me = String(Math.random())
    await update($, gen, () => me)
    const own = (ms: number, fn: () => Promise<unknown> | unknown) => {
      const tm = $.clock.every(ms, async () => {
        if ((await read($, gen)) !== me) return tm.cancel()
        await fn()
      })
    }
    // ponytail: polling de 2s, trocar por eventos se pesar
    own(2000, async () => {
      const [model, u, agents, home] = await Promise.all([
        $.session.model(), $.session.usage(), $.agent.list(), $.env.get('HOME'),
      ])
      // ponytail: o plugin grava o modo ativo nesse arquivo; ausente = desligado
      const flag = await $.fs.read(`${home}/.claude/.ponytail-active`).catch(() => '')
      await update($, snap, () => ({
        model,
        pct: u.context.percent ?? 0,
        tokens: u.context.tokens ?? 0,
        window: u.context.window,
        usd: u.cost?.usd ?? 0,
        startedAt: u.startedAt,
        ponytail: (flag.split('\n')[0] ?? '').trim() || (flag ? 'full' : ''),
        agents: agents.map(a => ({ id: a.id, type: a.type, description: a.description, status: a.status })),
      }))
      // contexto e custo: o personagem avisa ao cruzar 60%/85% e a cada alertUsd gastos
      const pct = u.context.percent ?? 0
      if (pct < 50) warned.clear()
      else if (pct >= 85 && !warned.has('85')) {
        warned.add('85'); warned.add('60')
        ping($, 'Contexto em 85%. Hora de /compact.')
        await react($, 'ask', '', undefined, 'Contexto em 85%! Faz um /compact antes que eu esqueça tudo.')
      } else if (pct >= 60 && !warned.has('60')) {
        warned.add('60')
        await react($, 'pause', '', undefined, 'Contexto passou de 60%. Dá pra pensar num /compact.')
      }
      const usd = u.cost?.usd ?? 0
      const step = Math.floor(usd / alertUsd)
      if (costStep < 0) costStep = step
      else if (step > costStep) {
        costStep = step
        ping($, `Sessão já custou US$ ${usd.toFixed(2)}.`)
        await react($, 'pause', '', undefined, `Já são US$ ${usd.toFixed(2)} nessa sessão. A carteira sentiu.`)
      }
    })
    // clima pelo IP, de hora em hora (wttr.in); falhou, o palco segue sem clima
    const fetchWeather = async () => {
      if (Date.now() - (await read($, weather)).at < 3600_000) return
      const r = await $.http.fetch('https://wttr.in/?format=%t|%C&lang=pt').catch(() => null)
      const [t, d] = r?.ok ? r.text.trim().split('|') : []
      if (!d) return
      const temp = Number.parseInt((t ?? '').replace('+', ''), 10)
      await update($, weather, () => ({ temp: Number.isNaN(temp) ? null : temp, desc: d.trim(), at: Date.now() }))
    }
    void fetchWeather()
    own(3600_000, fetchWeather)
    // faixa da tela inteira: ~12 quadros/s só enquanto ela existe
    own(80, () => {
      if (!band) return
      if (Date.now() - band.start > BAND_MS[band.kind]) band = null
      $.ui.invalidate('ui.render')
    })
    // ponytail: redesenha o painel a cada 700ms por causa do palco; subir o intervalo se pesar
    own(700, async () => {
      const n = await update($, tick, x => x + 1)
      if (pomo && Date.now() >= pomo.end) {
        const { min } = pomo
        pomo = null
        ping($, `Pomodoro de ${min} min acabou. Levanta e bebe água.`)
        $.ui.toast('Pomodoro acabou! Hora da pausa.', { timeoutMs: 6000 })
        await react($, 'pause', '', undefined, 'Pomodoro acabou! Levanta, alonga e bebe água.')
        await gain($, 30, 'focus')
      }
      const f = await read($, force)
      const sc = scene(n, SEED, NAMES, room, f)
      const forced = n > f.at && n - f.at < 200 && sc.seed === 0 && f.loud === true
      // quarta parede: quando a magia chega à borda do painel, atravessa a tela (faixa acima
      // do prompt) e solta um toast. Metade das especiais naturais; a do /especial sempre.
      const cx = Math.floor((room - SPRITE_W) / 2)
      const reacting = n > f.at && n - f.at < 200 && sc.seed === 0
      if (sc.fx && sc.fx.t === escapeAt(sc.fx.kind, cx, room) && (reacting || sc.seed % 2 === 0)) {
        band = { kind: sc.fx.kind, start: Date.now(), power: sc.fx.power }
        if (sc.fx.kind === 'coin' || sc.fx.kind === 'fairy') coins++
        const msg = escape(sc.fx.kind, NAMES[sc.idx]!, coins)
        // reações a eventos não soltam toast (seriam a cada turno), a não ser carregadas; o /especial e as naturais sim
        if (msg && (forced || !reacting || sc.fx.power)) $.ui.toast(sc.fx.power ? `Especial carregado! ${msg}` : msg, { timeoutMs: 5000 })
      }
    })
    return next(e)
  })

  on('command.run', { command: 'sidebar' }, async $ => {
    const r = await $.ui.open({ id: PANE, title: 'Sessão', columns: 34 })
    return { text: r.isPlaced ? 'Barra lateral aberta.' : 'Sem espaço: alargue o terminal (110+ colunas) e rode /sidebar de novo.' }
  })

  on('command.run', { command: 'especial' }, async ($, e) => {
    const n = await read($, tick)
    const words = e.args.trim().toLowerCase().split(/\s+/).filter(Boolean)
    const strong = words.some(w => /^(forte|carregad)/.test(w))
    const want = words.filter(w => !/^(forte|carregad)/.test(w)).join(' ')
    const cur = scene(n, SEED, NAMES, room, await read($, force)).idx
    const idx = want ? NAMES.findIndex(x => x.toLowerCase().includes(want)) : cur
    if (idx < 0) return { text: `Não conheço "${want}". Personagens: ${NAMES.join(', ')}.` }
    await update($, force, () => ({ at: n, idx, loud: true, power: strong ? 2 : undefined }))
    return { text: `${NAMES[idx]} vai soltar a especial${strong ? ' carregada' : ''}!` }
  })

  on('command.run', { command: 'pomodoro' }, async (_$, e) => {
    const a = e.args.trim().toLowerCase()
    if (/^(parar|stop|cancel)/.test(a)) { pomo = null; return { text: 'Pomodoro cancelado.' } }
    const min = Number.parseInt(a, 10) || Number(options?.pomodoro_min ?? 25)
    pomo = { end: Date.now() + min * 60_000, min }
    return { text: `Pomodoro de ${min} min começou. Foco!` }
  })

  on('command.run', { command: 'encontro' }, async ($, e) => {
    const n = await read($, tick)
    const want = e.args.trim().toLowerCase()
    const pairs = NAMES.filter(x => partner(x))
    const idx = want
      ? NAMES.findIndex(x => partner(x) && x.toLowerCase().includes(want))
      : NAMES.indexOf(pairs[n % pairs.length]!)
    if (idx < 0) return { text: `Encontros: ${pairs.join(', ')}.` }
    await update($, force, () => ({ at: n, idx, enc: true }))
    return { text: `${NAMES[idx]} e ${partner(NAMES[idx]!)!.guest} vão se encontrar no palco!` }
  })

  on('tool.call', { tool: 'TodoWrite' }, async ($, e, next) => {
    const list: Todo[] = e.todos.map(x => ({ content: x.content, status: x.status }))
    const before = (await read($, todos)).filter(x => x.status === 'completed').length
    await update($, todos, () => list)
    for (const x of list) if (x.status === 'in_progress' && !began.has(x.content)) began.set(x.content, Date.now())
    if (list.filter(x => x.status === 'completed').length > before) {
      const n = await read($, tick)
      await update($, banner, () => ({ kind: 'done', at: n }))
      const fresh = list.filter(x => x.status === 'completed').at(-1)
      // tarefa longa (5+ min em andamento) = especial carregada
      const since = fresh ? began.get(fresh.content) : undefined
      const power = since && Date.now() - since >= chargeMs ? 2 : undefined
      await gain($, power ? 50 : 10, 'tasks')
      await react($, 'done', fresh?.content ?? 'tarefa', power)
    }
    if (began.size > 100) began.clear()
    return next(e)
  })

  on('tool.call', async ($, e, next) => {
    const file = 'file_path' in e && typeof e.file_path === 'string' ? e.file_path : ''
    await update($, last, () => ({ tool: e.tool, file }))
    const res = await next(e)
    if (e.tool === 'Bash' && 'isError' in res && res.isError) {
      // ponytail: qualquer exit != 0 conta (até grep sem match); no máximo 1 a cada ~4min
      const n = await read($, tick)
      const ev = await read($, banner)
      if (ev.kind !== 'died' || n - ev.at > 340) {
        await update($, banner, () => ({ kind: 'died', at: n }))
        await gain($, 0, 'deaths')
      }
      if (++boss.streak === 3) {
        boss.name = BOSSES[Math.floor(Math.random() * BOSSES.length)]!
        $.ui.toast(`CHEFÃO: ${boss.name} apareceu! Corrija o erro pra derrotá-lo.`, { timeoutMs: 6000 })
      }
    } else if (e.tool === 'Bash' && 'isError' in res) {
      if (boss.streak >= 3) {
        const nome = boss.name
        await gain($, 40, 'bosses')
        await react($, 'done', nome, undefined, `${nome} derrotado! +40 XP.`)
      }
      boss.streak = 0
    }
    return res
  })

  on('tool.check', async ($, e, next) => {
    const v = await next(e)
    if (v.decision === 'ask') {
      ping($, `Claude pede autorização: ${e.tool}`)
      await react($, 'ask', e.tool)
    }
    return v
  })

  on('turn.complete', async ($, e, next) => {
    if (!('agentId' in e && e.agentId)) {
      await react($, e.isAborted ? 'abort' : 'pause', '')
      // avisa fora do terminal só quando o turno foi longo (dá tempo de ter saído da frente da tela)
      if (!e.isAborted && e.durationMs >= 60_000) ping($, `Claude terminou (${Math.round(e.durationMs / 1000)} s).`)
    }
    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const b = band
    if (!b || e.props.hasSurvey) return next(e)
    const ms = Date.now() - b.start
    if (ms > BAND_MS[b.kind]) return next(e)
    const { Box, Text } = $.ui.resolve(e)
    const g = bandGrid(b.kind, ms, e.props.bodyColumns, b.power)
    const lines = g.filter((_, y) => y % 2 === 0).map((_, r) => {
      const y = r * 2
      const segs: { ch: string; fg?: string; bg?: string; text: string }[] = []
      g[y]!.forEach((top, x) => {
        const bot = g[y + 1]![x]!
        const cell = !top && !bot ? { ch: ' ' } : !bot ? { ch: '▀', fg: top } : !top ? { ch: '▄', fg: bot } : { ch: '▀', fg: top, bg: bot }
        const last = segs[segs.length - 1]
        if (last && last.ch === cell.ch && last.fg === cell.fg && last.bg === cell.bg) last.text += cell.ch
        else segs.push({ ...cell, text: cell.ch })
      })
      return <Text wrap="truncate-end">{segs.map(s => s.fg ? <Text color={s.fg} backgroundColor={s.bg}>{s.text}</Text> : <Text>{s.text}</Text>)}</Text>
    })
    return <Box flexDirection="column">{lines}</Box>
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text } = $.ui.resolve(e)
    const s = await read($, snap)
    const t = await read($, todos)
    const n = await read($, tick)
    const w = Math.max(10, (e.props.bodyColumns ?? 30) - 4)
    const live = s.agents.filter(a => a.status === 'running' || a.status === 'waiting')
    const done = t.filter(x => x.status === 'completed').length
    const tone = s.pct >= 85 ? 'error' : s.pct >= 60 ? 'warning' : 'success'
    room = e.props.bodyColumns ?? 30
    const sc: Scene = scene(n, SEED, NAMES, room, await read($, force))
    const sp = SPRITES[sc.idx]!
    const frame = Math.floor(n / 2) % 2
    const px = flipped(((sc.alt && sp.alt) || sp.frames)[frame]!, sc.flip)
    const gsp = sc.guest && byName(sc.guest.name)
    const guestPx = gsp && sc.guest ? flipped(((sc.guest.alt && gsp.alt) || gsp.frames)[frame]!, sc.guest.flip) : undefined
    const hatSp = sc.hat ? byName(sc.hat) : undefined
    const now = new Date()
    const wx = await read($, weather)
    // estimativa das linhas dos cartões; sem espaço, some o cartão de agentes vazio pro palco caber
    const cardRows = 5 + 4 + 3 + 3 + 3 + (pomo ? 4 : 0) + (boss.streak >= 3 ? 4 : 0) + Math.max(1, live.length) + 4 + Math.min(t.length, 6)
    const roomy = (e.props.scroll?.bodyRows ?? 99) >= cardRows + STAGE_ROWS
    const canvas = cells(paint(n, room, sc, px, now, wx, { guest: guestPx, hat: hatSp && mainColor(hatSp) }))
    if (sc.talk) {
      // no encontro, o balão aponta pra quem fala (anfitrião ou convidado)
      const who = sc.talk.who === 'guest' && sc.guest ? sc.guest : { name: sp.name, x: sc.x, hop: sc.hop }
      let text = lines.get(sc.talk.key)
      if (!text) {
        const lt = await read($, last)
        text = sc.talk.kind === 'enc'
          ? encLine(who.name, sc.talk.line ?? 0, sc.seed + n)
          : say(sc.talk.kind, sp.name, sc.fx?.kind ?? null, sc.seed, {
            s, t, last: lt, mins: (Date.now() - s.startedAt) / 60000, now, weather: wx,
          })
        if (sc.talk.kind === 'shout' && sc.fx?.power && !text.startsWith('CARREGADO')) text = `CARREGADO! ${text}`
        if (lines.size > 30) lines.clear()
        lines.set(sc.talk.key, text)
      }
      const width = Math.min(room, Math.max(18, Math.min(text.length, 26) + 4))
      const head = Math.max(1, Math.min(room - 2, who.x + SPRITE_W / 2))
      const left = Math.min(Math.max(0, head - Math.floor(width / 2)), room - width)
      const bb = bubble(who.name, text, sc.talk.since, width, head - left, n % 2 === 0)
      const headRow = Math.floor((STAGE_ROWS * 2 - 3 - 19 - who.hop) / 2) // linha do topo da cabeça no palco
      const top = headRow - (bb.body.length + 3)
      stamp(canvas, top, left, bb.top, 'line')
      stamp(canvas, top, left + 2, ` ${who.name} `, '#e8875f', { bold: true })
      bb.body.forEach((l, i) => {
        stamp(canvas, top + 1 + i, left, l, 'line')
        stamp(canvas, top + 1 + i, left + 2, l.slice(2, -2), 'ink', { bold: true })
      })
      stamp(canvas, top + 1 + bb.body.length, left, bb.bottom, 'line')
      stamp(canvas, top + 2 + bb.body.length, left, bb.stem, 'line', { skipSpaces: true })
    }
    const ev = await read($, banner)
    if (n - ev.at < 7) {
      const msg = ev.kind === 'died' ? ' VOCÊ MORREU ' : ' TAREFA CONCLUÍDA '
      stamp(canvas, 3, Math.max(0, Math.floor((room - msg.length) / 2)), msg, ev.kind === 'died' ? '#e04a3a' : '#f0c040', { bold: true })
    }
    const stage = merge(canvas).map(line => (
      <Text wrap="truncate-end">{line.map(seg => <Text color={seg.fg} backgroundColor={seg.bg} bold={seg.bold}>{seg.text}</Text>)}</Text>
    ))
    const card = (title: string, right: string | undefined, body: any) => (
      <Box flexDirection="column" borderStyle="round" borderColor="subtle" paddingX={1}>
        <Box justifyContent="space-between">
          <Text bold color="claude">{title}</Text>
          {right && <Text color="subtle">{right}</Text>}
        </Box>
        {body}
      </Box>
    )
    return (
      <Box flexDirection="column" minHeight={e.props.scroll?.bodyRows} justifyContent="space-between">
        <Box flexDirection="column">
        {card('MODELO', mins(Date.now() - s.startedAt), (
          <Box flexDirection="column">
            <Text bold>{s.model || '…'}</Text>
            {s.ponytail && (
              <Text color={s.ponytail === 'ultra' ? 'warning' : 'success'}>
                [PONYTAIL{s.ponytail === 'full' ? '' : `:${s.ponytail.toUpperCase()}`}]
              </Text>
            )}
          </Box>
        ))}
        {card('CONTEXTO', `${Math.round(s.pct)}%`, (
          <Box flexDirection="column">
            <Text color={tone}>{bar(s.pct, w)}</Text>
            <Text color="subtle">{k(s.tokens)} de {k(s.window)} tokens</Text>
          </Box>
        ))}
        {card('CUSTO', undefined, (
          <Text bold color="success">US$ {s.usd.toFixed(2)}</Text>
        ))}
        {card('NÍVEL', `${stats.xp} XP`, (
          <Box flexDirection="column">
            <Text color="suggestion">Nv {level(stats.xp)} <Text color="subtle">{stats.got.length}/{ACH.length} conquistas</Text></Text>
            <Text color="suggestion">{bar(((stats.xp - 25 * (level(stats.xp) - 1) ** 2) / (25 * (2 * level(stats.xp) - 1))) * 100, w)}</Text>
          </Box>
        ))}
        {pomo && card('FOCO', `${pomo.min} min`, (
          <Box flexDirection="column">
            <Text bold color="warning">{Math.floor(Math.max(0, pomo.end - Date.now()) / 60000)}:{String(Math.floor((Math.max(0, pomo.end - Date.now()) % 60000) / 1000)).padStart(2, '0')}</Text>
            <Text color="warning">{bar((1 - (pomo.end - Date.now()) / (pomo.min * 60000)) * 100, w)}</Text>
          </Box>
        ))}
        {boss.streak >= 3 && card('CHEFÃO', boss.name, (
          <Text color="error">{'♥'.repeat(Math.min(boss.streak, 10))} <Text color="subtle">{boss.streak} erros seguidos</Text></Text>
        ))}
        {(live.length > 0 || roomy) && card('AGENTES', String(live.length), (
          <Box flexDirection="column">
            {live.length === 0 && <Text color="inactive">nenhum ativo</Text>}
            {live.map(a => (
              <Text color="warning" wrap="truncate">● {a.type} <Text color="subtle">{a.description}</Text></Text>
            ))}
          </Box>
        ))}
        {card('TAREFAS', t.length ? `${done}/${t.length}` : undefined, (
          <Box flexDirection="column">
            {t.length === 0 && <Text color="inactive">sem checklist</Text>}
            {t.length > 0 && <Text color="success">{bar((done / t.length) * 100, w)}</Text>}
            {t.length > 5 && <Text color="inactive">+{t.length - 5} mais</Text>}
            {t.slice(t.length > 5 ? Math.max(0, Math.min(t.findIndex(x => x.status !== 'completed'), t.length - 5)) : 0).slice(0, 5).map(x => (
              <Text
                wrap="truncate"
                color={x.status === 'in_progress' ? 'suggestion' : x.status === 'completed' ? 'inactive' : undefined}
                strikethrough={x.status === 'completed'}
              >
                {x.status === 'completed' ? '✔' : x.status === 'in_progress' ? '▶' : '○'} {x.content}
              </Text>
            ))}
          </Box>
        ))}
        </Box>
        <Box flexDirection="column">{stage}</Box>
      </Box>
    )
  })
}

files.hooks/band.ts:
// A especial que "vaza" do painel: faixa acima do prompt, na largura da conversa,
// 2 linhas (4 px) de altura, da direita (onde fica o painel) para a esquerda. Fundo transparente.
import type { Grid } from './sprites'
import type { FxKind } from './stage'
import { hash } from './stage'
import { halo } from './world'

export const BAND_MS: Record<FxKind, number> = {
  beam: 2200, shot: 1300, missile: 1500, hadouken: 1600, bolt: 1300, dash: 1000,
  chomp: 2600, coin: 1800, ring: 1400, wind: 1800, grenade: 1900, roll: 1800,
  gaster: 2200, harpoon: 2000, ice: 2200, glitch: 1400, fairy: 2000, duck: 2200, boom: 1700, whip: 1500,
  bomb: 1900, barrel: 2000, egg: 1800, sonicboom: 1400, omni: 1600, chains: 1800, airdash: 1100,
  invaders: 2400, lance: 1500, vent: 2000,
}

/** Faixa da especial; carregada (power) ganha 2 px de brilho em volta e fica com 3 linhas. */
export function bandGrid(kind: FxKind, ms: number, W: number, power?: number): Grid {
  const g = draw(kind, ms, W)
  if (!power) return g
  const big: Grid = [Array<string>(W).fill(''), ...g, Array<string>(W).fill('')]
  halo(big)
  return big
}

function draw(kind: FxKind, ms: number, W: number): Grid {
  const H = 4
  const g: Grid = Array.from({ length: H }, () => Array<string>(W).fill(''))
  const put = (x: number, y: number, c: string) => {
    x = Math.round(x)
    if (x >= 0 && x < W && y >= 0 && y < H) g[y]![x] = c
  }
  const p = Math.min(1, ms / BAND_MS[kind]) // progresso 0..1
  const lead = W - p * (W + 12) // frente do efeito, vindo da direita
  switch (kind) {
    case 'beam': { // feixe cresce da direita até a borda esquerda, segura e afina
      const front = Math.max(-2, W - Math.min(1, p / 0.45) * (W + 2))
      const thin = p > 0.85
      for (let x = Math.ceil(front); x < W; x++) {
        if (!thin) { put(x, 0, '#5fd8ff'); put(x, 3, '#5fd8ff') }
        put(x, 1, '#ffffff'); put(x, 2, thin ? '#5fd8ff' : '#ffffff')
      }
      if (p < 0.45) for (let y = 0; y < 4; y++) for (let d = -1; d <= 1; d++) put(front + d, y, d === 0 ? '#ffffff' : '#bff0ff')
      if (p >= 0.45 && p < 0.8) for (let i = 0; i < 6; i++) put(hash(i + Math.floor(ms / 90)) % 4, hash(i * 3) % 4, '#ffe066')
      break
    }
    case 'shot': case 'hadouken': case 'missile': {
      const x = lead
      if (kind === 'shot') {
        for (let y = 1; y < 3; y++) for (let d = 0; d < 3; d++) put(x + d, y, d === 0 ? '#fff6a0' : '#ffd23a')
        put(x + 4, 1, '#ffe98a'); put(x + 6, 2, '#ffe98a')
      } else if (kind === 'hadouken') {
        const wob = Math.floor(ms / 80) % 2
        for (let y = 0; y < 4; y++) for (let d = 0; d < 4; d++) put(x + d, y, (y === 1 || y === 2) && d < 3 ? '#e6f6ff' : '#5ab0ff')
        put(x + 5 + wob, 1, '#5ab0ff'); put(x + 7, 2 - wob, '#3a80d0'); put(x + 9, 1, '#3a80d0')
      } else {
        put(x, 1, '#ff4a3a'); put(x, 2, '#ff4a3a')
        for (let d = 1; d < 6; d++) { put(x + d, 1, '#f08a24'); put(x + d, 2, '#c86a14') }
        for (let i = 0; i < 6; i++) put(x + 8 + i * 3, (i + Math.floor(ms / 100)) % 4, ['#c0c0c0', '#9a9a9a', '#7a7a7a'][i % 3]!)
      }
      break
    }
    case 'dash': { // Sonic em bola, com rastro
      const x = lead
      for (let y = 0; y < 4; y++) for (let d = 0; d < 4; d++) {
        if ((y === 0 || y === 3) && (d === 0 || d === 3)) continue
        put(x + d, y, d < 2 && y < 2 ? '#5a9cff' : '#2a6ee6')
      }
      for (const y of [0, 1, 2, 3]) for (let d = 5; d < 5 + 10 + y * 3; d += 2) put(x + d, y, d < 9 ? '#cfe6ff' : '#7fb6ff')
      break
    }
    case 'chomp': { // Pac-Man atravessa comendo os pontinhos
      const x = lead
      for (let d = 2; d < W; d += 4) if (d < x) { put(d, 1, '#ffe9c4'); put(d + 1, 1, '#ffe9c4') }
      const open = Math.floor(ms / 120) % 2 === 0
      const pac = open ? ['YYY.', '..YY', '..YY', 'YYY.'] : ['.YY.', 'YYYY', 'YYYY', '.YY.']
      pac.forEach((row, y) => [...row].forEach((ch, d) => { if (ch === 'Y') put(x + d, y, '#f6d33a') }))
      break
    }
    case 'coin': { // moedas pulando pela tela
      for (let i = 0; i < 5; i++) {
        const x = lead + i * 7
        const y = Math.round(Math.abs(Math.sin(ms / 140 + i)) * 2)
        const w = (Math.floor(ms / 100) + i) % 2 ? 1 : 2
        for (let d = 0; d < w; d++) { put(x + d, y, '#fff6a0'); put(x + d, y + 1, '#f6d33a') }
      }
      break
    }
    case 'ring': { // raio da espada do Link (vida cheia!)
      const x = lead
      for (let d = 0; d < 7; d++) { put(x + d, 1, d === 0 ? '#ffffff' : '#dff2ff'); put(x + d, 2, '#9fd6ff') }
      put(x + 7, 0, '#e8c84a'); put(x + 7, 3, '#e8c84a'); put(x + 7, 1, '#7a4a24'); put(x + 7, 2, '#7a4a24')
      put(x + 8, 1, '#7a4a24'); put(x + 8, 2, '#7a4a24')
      if (Math.floor(ms / 70) % 2) for (let i = 0; i < 3; i++) put(x + 10 + i * 4, i % 4, '#ffffff')
      break
    }
    case 'wind': { // Kirby suga a tela: correntes indo pro painel
      for (let i = 0; i < 9; i++) {
        const x = (hash(i * 11) % W) + p * W * 1.4
        const y = hash(i * 5) % 4
        for (let d = 0; d < 4; d++) put((x + d) % W, y, d === 3 ? '#ffffff' : '#cfe9ff')
      }
      break
    }
    case 'grenade': { // granada voa e explode no meio da tela
      if (p < 0.5) {
        const x = W - (p / 0.5) * W * 0.6
        put(x, Math.round(3 - Math.sin((p / 0.5) * Math.PI) * 3), '#4a6a3a')
      } else {
        const ex = W * 0.4
        const r = Math.min(8, (p - 0.5) * 30)
        for (let y = 0; y < 4; y++) for (let d = -r; d <= r; d++) {
          if (Math.abs(d) + Math.abs(y - 1.5) * 2 > r) continue
          const k = Math.abs(d) / Math.max(1, r)
          put(ex + d, y, p > 0.8 ? (k < 0.5 ? '#9a9a9a' : '#6a6a6a') : k < 0.4 ? '#fff6a0' : k < 0.7 ? '#ffd23a' : '#ff7a2a')
        }
      }
      break
    }
    case 'bolt': { // relâmpago horizontal piscando
      if (Math.floor(ms / 110) % 3 === 2) break
      let y = 1
      for (let x = W - 1; x >= 0; x--) {
        if (x % 3 === 0) y = Math.max(0, Math.min(3, y + (hash(x + Math.floor(ms / 220)) % 3) - 1))
        put(x, y, '#fff27a')
        if (hash(x) % 4 === 0) put(x, Math.min(3, y + 1), '#ffd23a')
      }
      break
    }
    case 'gaster': { // caveira na beirada direita e o feixe atravessando
      const front = Math.max(-2, W - 8 - Math.min(1, p / 0.4) * W)
      const SK = ['.WW.', 'WkkW', 'WWWW', 'W.W.']
      SK.forEach((row, y) => [...row].forEach((ch, d) => { if (ch !== '.') put(W - 5 + d, y, ch === 'W' ? '#f2f2f2' : '#5fd8ff') }))
      if (p < 0.9) for (let x = Math.ceil(front); x < W - 5; x++) { put(x, 1, '#ffffff'); put(x, 2, p > 0.75 ? '#bfe8ff' : '#ffffff'); if (p <= 0.75) { put(x, 0, '#bfe8ff'); put(x, 3, '#bfe8ff') } }
      break
    }
    case 'harpoon': { // vai até a borda esquerda e volta puxando um pedaço
      const tip = p < 0.5 ? W - (p / 0.5) * (W + 2) : -2 + ((p - 0.5) / 0.5) * (W + 2)
      for (let x = Math.ceil(tip) + 1; x < W; x++) put(x, 1, x % 2 ? '#c8a040' : '#8a6a2a')
      put(tip, 0, '#e0e0e8'); put(tip, 1, '#ffffff'); put(tip, 2, '#e0e0e8'); put(tip - 1, 1, '#c9ced8')
      if (p >= 0.5) for (let d = 1; d <= 6; d++) { put(tip - 1 - d, 2, '#c9ced8'); put(tip - 1 - d, 3, '#8a8f9a') }
      break
    }
    case 'ice': { // bola de gelo, a faixa congela e racha
      if (p < 0.45) {
        const x = W - (p / 0.45) * (W + 6)
        for (let y = 1; y < 3; y++) for (let d = 0; d < 3; d++) put(x + d, y, d === 0 ? '#ffffff' : '#5ab8f0')
        for (let i = 1; i < 6; i++) put(x + 3 + i * 2, (i % 2) + 1, '#bfe8ff')
      } else {
        const crack = p > 0.75
        for (let x = 0; x < W; x++) for (let y = 0; y < 4; y++) {
          const h = hash(x * 4 + y)
          if (crack && h % 4 === 0) continue
          const fall = crack ? Math.floor((p - 0.75) * 20 * ((h % 3) + 1)) : 0
          if (y === 3 || h % 5 === 0) put(x, y + fall, h % 7 === 0 ? '#ffffff' : '#9fd6ff')
        }
      }
      break
    }
    case 'glitch': { // blocos corrompidos que vão se consertando
      const tick = Math.floor(ms / 80)
      for (let i = 0; i < W / 3; i++) {
        const h = hash(i * 7 + tick * 131)
        if (h % 100 >= 45 * (1 - p)) continue
        const col = ['#ff00ff', '#00ffff', '#ffff00', '#9a8ab0', '#e8e8f0'][h % 5]!
        for (let d = 0; d < 3; d++) put(i * 3 + d, (h >> 6) % 4, col)
      }
      break
    }
    case 'fairy': { // Navi atravessa em zigue-zague deixando brilho
      const at = (k: number) => [lead + k * 3, Math.round(1.5 + Math.sin((ms - k * 60) / 90) * 1.5)] as const
      for (let k = 6; k >= 0; k--) {
        const [x, y] = at(k)
        put(x, y, k === 0 ? '#ffffff' : k < 3 ? '#bfe8ff' : '#7fc8ff')
      }
      put(lead, at(0)[1] + 1, '#bfe8ff')
      break
    }
    case 'duck': { // patos cruzam, levam tiro e caem
      for (let i = 0; i < 2; i++) {
        const x = W - Math.min(p, 0.6) / 0.6 * W * 0.8 + i * 10
        const y = p < 0.6 ? 1 - i % 2 : 1 + Math.floor((p - 0.6) * 25)
        const flap = Math.floor(ms / 120 + i) % 2
        put(x, y, '#2a8a3a'); put(x - 1, y, '#ffd23a'); put(x + 1, y + 1, '#8a5a2a'); put(x, y + 1, '#8a5a2a')
        if (p < 0.6) put(x + 1, y + (flap ? 0 : 2), '#c8a070')
        if (p >= 0.6 && p < 0.68) { put(x - 1, y - 1, '#ffffff'); put(x + 2, y - 1, '#ffffff') }
      }
      break
    }
    case 'boom': { // explosão do creeper na beirada do painel, blocos voando
      const ex = W * 0.88
      const r = Math.min(10, p * 36)
      for (let y = 0; y < 4; y++) for (let d = -r; d <= r; d++) {
        if (Math.abs(d) + Math.abs(y - 1.5) * 2 > r) continue
        const k = Math.abs(d) / Math.max(1, r)
        put(ex + d, y, p > 0.75 ? (k < 0.5 ? '#9a9a9a' : '#6a6a6a') : k < 0.4 ? '#ffffff' : k < 0.7 ? '#ffe066' : '#ff7a2a')
      }
      for (let i = 0; i < 8; i++) put(ex - p * W * (0.3 + (hash(i) % 7) / 10), (hash(i * 3) % 4), i % 2 ? '#5ab84a' : '#3a8a32')
      break
    }
    case 'whip': case 'chains': { // estica até a borda, segura e recolhe
      const ext = p < 0.4 ? p / 0.4 : p < 0.7 ? 1 : (1 - p) / 0.3
      const front = W - ext * (W + 2)
      const lines = kind === 'whip' ? [1] : [0, 3]
      for (const y of lines) {
        for (let x = Math.ceil(front); x < W; x++) put(x, y, x % 2 ? '#c9ced8' : '#8a8f9a')
        if (kind === 'whip') { put(front, 0, '#ff9a3a'); put(front, 2, '#ff9a3a'); put(front - 1, 1, '#ffe066') }
        else { put(front, y, '#ffe066'); put(front + 1, y, '#ff7a2a'); put(front + 2, y, '#c83a1a'); put(front + 1 + (Math.floor(ms / 90) % 3), y === 0 ? 1 : 2, '#ff9a3a') }
      }
      break
    }
    case 'bomb': { // chama em cruz atravessando a tela
      const len = Math.min(W, (p / 0.4) * W)
      const fade = p > 0.8
      for (let x = W - 1; x >= W - len; x--) for (let y = 0; y < 4; y++) {
        if (fade && hash(x * 4 + y + Math.floor(ms / 100)) % 3) continue
        put(x, y, fade ? '#8a8a8a' : y === 1 || y === 2 ? '#ffffff' : x < W - len + 3 ? '#ff7a2a' : '#ffe066')
      }
      break
    }
    case 'barrel': { // barris rolando
      for (let i = 0; i < 3; i++) {
        const x = lead + i * 11
        for (let y = 0; y < 4; y++) for (let d = 0; d < 4; d++) {
          if ((y === 0 || y === 3) && (d === 0 || d === 3)) continue
          put(x + d, y, (d + Math.floor(ms / 90)) % 3 === 0 ? '#5a3a1a' : '#a06a30')
        }
      }
      break
    }
    case 'egg': { // ovo quicando
      const x = lead
      const y = Math.round(Math.abs(Math.sin(ms / 160)) * 1) - 1
      for (let dy = 0; dy < 4; dy++) for (let d = 0; d < 3; d++) {
        if ((dy === 0 || dy === 3) && d !== 1) continue
        put(x + d, y + dy, (d + dy + Math.floor(ms / 120)) % 3 === 0 ? '#4ac040' : '#f8f8f8')
      }
      break
    }
    case 'sonicboom': { // dois crescentes girando
      for (let i = 0; i < 2; i++) {
        const x = lead + i * 9
        const wob = Math.floor(ms / 70) % 2
        for (let y = 0; y < 4; y++) {
          const bend = Math.round(((y - 1.5) ** 2) / 1.2)
          put(x + bend, y, y === 1 || y === 2 ? '#ffffff' : '#ffe066')
          put(x + bend + 1 + wob, y, '#fff6a0')
        }
      }
      break
    }
    case 'omni': { // cortes diagonais pipocando pela tela
      for (let i = 0; i < 9; i++) {
        const born = i / 11
        if (p < born || p > born + 0.18) continue
        const x0 = hash(i * 19 + 3) % Math.max(1, W - 4)
        const dir = i % 2 ? 1 : -1
        for (let y = 0; y < 4; y++) put(x0 + (dir > 0 ? y : 3 - y), y, p < born + 0.08 ? '#ffffff' : '#9fd6ff')
      }
      break
    }
    case 'airdash': { // rastro rosa e azul
      const x = lead
      for (let d = 0; d < 16; d++) for (const y of [1, 2]) put(x + d, y - (d > 8 ? 1 : 0), d < 3 ? '#ffffff' : d < 9 ? '#ff8ab8' : '#8ad8ff')
      for (let i = 0; i < 4; i++) put(x + 4 + hash(i + Math.floor(ms / 100)) % 14, i % 2 ? 0 : 3, '#ffd6ea')
      break
    }
    case 'invaders': { // fileira marchando pra esquerda; um explode
      const step = Math.floor(ms / 250)
      const INV = ['.g.g.', 'ggggg', 'g.g.g']
      for (let i = 0; i < 6; i++) {
        const x = W - 4 - step * 3 + i * 8 - (W * 0.2)
        if (i === 2 && p > 0.55) { if (p < 0.7) for (let k = 0; k < 5; k++) put(x + hash(k + step) % 6, hash(k * 3) % 4, '#ffffff'); continue }
        INV.forEach((row, y) => [...row].forEach((ch, d) => { if (ch === 'g') put(x + d, y + (step % 2), '#5adc5a') }))
      }
      break
    }
    case 'lance': { // lanças voando
      for (let i = 0; i < 3; i++) {
        const x = lead + i * 14
        for (let d = 0; d < 7; d++) put(x + d, 1, '#c9ced8')
        put(x - 1, 1, '#ffffff'); put(x, 0, '#e8e8f0'); put(x, 2, '#e8e8f0')
      }
      break
    }
    case 'vent': { // sai de uma ventilação, corre e entra na outra
      for (const vx of [0, W - 6]) for (let d = 0; d < 6; d++) put(vx + d, 3, d % 2 ? '#2a2a33' : '#7a7f8a')
      if (p > 0.08 && p < 0.92) {
        const x = W - 6 - ((p - 0.08) / 0.84) * (W - 9)
        const y = Math.floor(ms / 120) % 2
        for (let d = 0; d < 3; d++) for (let dy = 0; dy < 3; dy++) put(x + d, y + dy, d === 0 && dy === 0 ? '#9ad8f0' : '#d8303a')
      }
      break
    }
    case 'roll': { // partículas douradas da Graça
      for (let i = 0; i < 12; i++) {
        const x = lead + hash(i * 7) % 30
        const y = (hash(i) + Math.floor(ms / 200)) % 4
        if ((i + Math.floor(ms / 150)) % 3) put(x, y, i % 2 ? '#f0c040' : '#fff0a0')
      }
      break
    }
  }
  return g
}

files.hooks/stage.ts:
// Diretor de cena: cada personagem fica TURN ticks (700ms) no palco, começando no centro.
// Roteiro do turno: entra falando o bordão; depois faz a especial (1 em 3), passeia ou dá pulinhos;
// no meio comenta algo; termina de volta ao centro.
export const TURN = 128 // ~90s
export const SPRITE_W = 16
const HELLO = [2, 16] as const
const ACT_AT = 24
const CHAT = [76, 94] as const

export type FxKind =
  | 'coin' | 'ring' | 'dash' | 'bolt' | 'roll' | 'chomp' | 'wind'
  | 'shot' | 'missile' | 'hadouken' | 'grenade' | 'beam'
  | 'gaster' | 'harpoon' | 'ice' | 'glitch' | 'fairy' | 'duck' | 'boom' | 'whip' | 'bomb'
  | 'barrel' | 'egg' | 'sonicboom' | 'omni' | 'chains' | 'airdash' | 'invaders' | 'lance' | 'vent'

export const SPECIAL: Record<string, FxKind> = {
  Mario: 'coin', Link: 'ring', Sonic: 'dash', Crono: 'bolt', Tarnished: 'roll',
  'Pac-Man': 'chomp', Kirby: 'wind', 'Mega Man': 'shot', Samus: 'missile',
  Pikachu: 'bolt', 'Master Chief': 'grenade', Goku: 'beam', Ryu: 'hadouken', 'Black Mage': 'bolt',
  Sans: 'gaster', Scorpion: 'harpoon', 'Sub-Zero': 'ice', 'MissingNo.': 'glitch', Navi: 'fairy',
  'Duck Hunt': 'duck', Creeper: 'boom', Simon: 'whip', Bomberman: 'bomb', 'Donkey Kong': 'barrel',
  Yoshi: 'egg', Guile: 'sonicboom', Cloud: 'omni', Kratos: 'chains', Madeline: 'airdash',
  Invader: 'invaders', Arthur: 'lance', Tripulante: 'vent',
}

// Encontros: dois personagens no palco ao mesmo tempo.
export type MeetKind = 'race' | 'duel' | 'chase'
const PAIRS: [string, string, MeetKind][] = [
  ['Mario', 'Sonic', 'race'], ['Ryu', 'Guile', 'duel'], ['Scorpion', 'Sub-Zero', 'duel'], ['Pac-Man', 'Blinky', 'chase'],
]
export function partner(name: string): { guest: string; kind: MeetKind } | null {
  for (const [a, b, kind] of PAIRS) {
    if (a === name) return { guest: b, kind }
    if (b === name) return { guest: a, kind }
  }
  return null
}

export const hash = (n: number) => {
  let h = (n ^ 0x9e3779b9) >>> 0
  h = Math.imul(h ^ (h >>> 16), 0x85ebca6b) >>> 0
  h = Math.imul(h ^ (h >>> 13), 0xc2b2ae35) >>> 0
  return (h ^ (h >>> 16)) >>> 0
}

// enc: fala do encontro; who diz quem fala (o balão aponta pra ele), line 0 abre e 1 responde
export type Talk = { kind: 'hello' | 'chat' | 'shout' | 'enc'; since: number; key: string; who?: 'guest'; line?: 0 | 1 }
export type Pose = { name: string; x: number; flip: boolean; hop: number; alt?: boolean }
export type Scene = {
  turn: number
  idx: number
  seed: number
  x: number
  flip: boolean
  hop: number
  fx: { kind: FxKind; t: number; power?: number } | null
  talk: Talk | null
  alt?: boolean // usa a variação do sprite (Madeline de cabelo azul, Arthur sem armadura)
  hat?: string // Kirby copiou alguém: chapéu na cor desse personagem
  guest?: Pose // encontro
  clash?: number // faísca do duelo nessa coluna
}

const HOPS = [0, 2, 4, 5, 5, 4, 2, 0]

/** Quanto dura a especial e onde o personagem está em cada tick dela. */
export function fxMotion(kind: FxKind, t: number, cx: number, W: number) {
  const right = W - SPRITE_W
  switch (kind) {
    case 'dash': { // sai correndo pela direita e volta pela esquerda
      const out = Math.ceil((W - cx) / 3)
      const back = Math.ceil((cx + SPRITE_W) / 3)
      const x = t < out ? cx + 3 * t : Math.min(cx, -SPRITE_W + 3 * (t - out))
      return { dur: out + back + 1, x, hop: 0, flip: false }
    }
    case 'roll': {
      const x = t < 5 ? cx - 2 * t : t < 8 ? cx - 10 : Math.min(cx, cx - 10 + 2 * (t - 8))
      return { dur: 14, x: Math.max(0, x), hop: t < 5 ? (t % 2) : 0, flip: t < 5 }
    }
    case 'chomp': { // anda pra direita comendo as pastilhas e volta
      const go = Math.max(0, Math.min(12, right - cx))
      const x = t < go ? cx + t : Math.max(cx, cx + go - (t - go))
      return { dur: 2 * go + 1, x, hop: 0, flip: t >= go }
    }
    case 'coin': return { dur: 10, x: cx, hop: HOPS[t] ?? 0, flip: false }
    case 'shot': case 'missile': case 'hadouken':
      return { dur: Math.ceil((W - cx) / 3) + 4, x: cx, hop: 0, flip: false }
    case 'beam': return { dur: 16, x: cx, hop: 0, flip: false }
    case 'grenade': return { dur: 14, x: cx, hop: 0, flip: false }
    case 'wind': return { dur: 14, x: cx, hop: 0, flip: false }
    case 'ring': return { dur: 12, x: cx, hop: t % 4 === 1 ? 1 : 0, flip: false }
    case 'bolt': return { dur: 10, x: cx, hop: 0, flip: false }
    case 'ice': case 'sonicboom': case 'barrel':
      return { dur: Math.ceil((W - cx) / 3) + 4, x: cx, hop: 0, flip: false }
    case 'lance': return { dur: Math.ceil((W - cx) / 4) + 8, x: cx, hop: 0, flip: false }
    case 'harpoon': { // ida e volta da corda
      const out = Math.ceil((cx + 3) / 4)
      return { dur: 2 * out + 3, x: cx, hop: 0, flip: false }
    }
    case 'glitch': return { dur: 10, x: t < 8 ? cx + [0, 1, -1][t % 3]! : cx, hop: 0, flip: t % 4 === 3 }
    case 'duck': return { dur: 16, x: cx, hop: [0, 2, 3, 2][t - 12] ?? 0, flip: false }
    case 'bomb': { // planta a bomba, recua e volta depois da explosão
      const back = t < 3 ? 0 : t < 7 ? t - 2 : t < 11 ? 4 : Math.max(0, 4 - 2 * (t - 10))
      return { dur: 14, x: Math.max(0, cx - back), hop: 0, flip: t >= 3 && t < 7 }
    }
    case 'omni': { // Cloud teleporta cortando
      const j = t < 10 ? (hash(t * 7 + 1) % 7) - 3 : 0
      return { dur: 14, x: Math.max(0, Math.min(right, cx + j)), hop: t < 10 ? hash(t) % 3 : 0, flip: t < 10 && t % 2 === 1 }
    }
    case 'airdash': { // dash na diagonal, pra cima e pra frente
      const d = [0, 0, 2, 4, 6, 8, 7, 6, 4, 3, 1, 0][t] ?? 0
      return { dur: 12, x: cx + Math.min(d, cx), hop: d, flip: false }
    }
    case 'vent': { // entra numa ventilação e sai na outra
      const x = t < 4 ? cx + t : t < 10 ? -999 : Math.min(cx, cx - 6 + (t - 10))
      return { dur: 17, x, hop: 0, flip: false }
    }
    case 'gaster': case 'chains': case 'egg': case 'boom': case 'invaders': case 'fairy':
      return { dur: kind === 'chains' ? 12 : kind === 'fairy' || kind === 'invaders' ? 16 : 14, x: cx, hop: 0, flip: false }
    case 'whip': return { dur: 10, x: cx, hop: 0, flip: false }
  }
}

// especial forçada a partir do tick `at` (loud: veio do /especial; power: carregada; enc: encontro em vez de especial)
export type Force = { at: number; idx: number; loud?: boolean; power?: number; enc?: boolean }

/** Especiais acontecem virados para a conversa (esquerda): o movimento é espelhado em torno do centro. */
export function fxMove(kind: FxKind, t: number, cx: number, W: number) {
  const m = fxMotion(kind, t, cx, W)
  return { ...m, x: 2 * cx - m.x, flip: !m.flip }
}

/** Tick da especial em que ela chega à borda esquerda do painel e "vaza" para a tela. */
export function escapeAt(kind: FxKind, cx: number, W: number): number {
  switch (kind) {
    case 'beam': return 5
    case 'shot': case 'missile': case 'hadouken': return Math.ceil(cx / 3)
    case 'dash': return Math.ceil((cx + SPRITE_W) / 3)
    case 'chomp': return Math.max(1, Math.min(12, W - SPRITE_W - cx))
    case 'grenade': return 5
    case 'ring': return 4
    case 'coin': return 3
    case 'roll': return 3
    case 'wind': case 'bolt': case 'glitch': return 2
    case 'ice': case 'sonicboom': case 'barrel': return Math.ceil(cx / 3)
    case 'lance': return Math.ceil(cx / 4)
    case 'harpoon': return Math.ceil((cx + 1) / 4)
    case 'gaster': case 'fairy': return 6
    case 'duck': return 5
    case 'boom': case 'vent': return 8
    case 'whip': case 'chains': case 'airdash': case 'invaders': return 4
    case 'bomb': case 'egg': return 7
    case 'omni': return 3
  }
}

/** Sequência da especial: o Kirby primeiro inspira e depois solta a especial de quem engoliu. */
function moves(name: string, copy: string): { kinds: FxKind[]; hat?: string } {
  const own = SPECIAL[name] ?? 'coin'
  if (name !== 'Kirby') return { kinds: [own] }
  const got = SPECIAL[copy]
  return got && got !== 'wind' ? { kinds: ['wind', got], hat: copy } : { kinds: ['wind'] }
}

/** Onde a especial está no tick `a` (null: acabou). */
function act(kinds: FxKind[], a: number, cx: number, W: number) {
  let t = a
  for (const [i, kind] of kinds.entries()) {
    const m = fxMove(kind, t, cx, W)
    if (t < m.dur) return { kind, t, m, part: i }
    t -= m.dur
  }
  return null
}

const lerp = (a: number, b: number, k: number) => Math.round(a + (b - a) * Math.max(0, Math.min(1, k)))
const wrapX = (p: number, W: number) => ((p + SPRITE_W) % (W + SPRITE_W) + W + SPRITE_W) % (W + SPRITE_W) - SPRITE_W

/** Coreografia do encontro no tick `a`; null quando acabou. */
export function meet(kind: MeetKind, a: number, cx: number, W: number) {
  const right = Math.max(0, W - SPRITE_W)
  let host = { x: cx, flip: false, hop: 0, alt: false }
  let guest = { x: W + 2, flip: true, hop: 0, alt: false }
  let clash: number | undefined
  let talk: { who?: 'guest'; line: 0 | 1; since: number } | undefined
  if (kind === 'chase') {
    // fantasma persegue o Pac-Man pra fora; ele volta com a pastilha de poder e o fantasma foge azul
    if (a < 28) {
      host = { x: cx - 2 * a, flip: true, hop: 0, alt: false }
      guest = { x: W - 2 * a + 6, flip: true, hop: 0, alt: false }
    } else {
      const b = a - 28
      host = { x: Math.min(cx, -SPRITE_W - 16 + 2 * b), flip: false, hop: 0, alt: false }
      guest = { x: -SPRITE_W + 2 * b, flip: false, hop: 0, alt: true }
      if (host.x === cx && guest.x > W) return null
    }
    if (a >= 1 && a < 9) talk = { line: 0, since: a - 1 }
    if (a >= 34 && a < 42) talk = { line: 1, since: a - 34 }
    return { host, guest, clash, talk }
  }
  // entrada: anfitrião vai pra esquerda, convidado entra pela direita, os dois se encaram
  if (a < 6) {
    host = { x: lerp(cx, 0, (a + 1) / 6), flip: true, hop: 0, alt: false }
    guest = { x: lerp(W + 2, right, (a + 1) / 6), flip: true, hop: 0, alt: false }
  } else {
    host = { x: 0, flip: false, hop: 0, alt: false }
    guest = { x: right, flip: true, hop: 0, alt: false }
  }
  if (a >= 6 && a < 14) talk = { line: 0, since: a - 6 }
  if (a >= 14 && a < 22) talk = { who: 'guest', line: 1, since: a - 14 }
  const b = a - 22
  if (kind === 'race' && b >= 0) {
    // os dois correm pra direita, dão a volta na tela; o convidado é mais rápido
    const lap = W + SPRITE_W
    const gp = Math.min(right + lap, right + 4 * b)
    const hp = Math.min(lap, 2 * b)
    guest = { x: wrapX(gp, W), flip: gp === right + lap, hop: gp === right + lap && b % 2 ? 2 : 0, alt: false }
    host = { x: wrapX(hp, W), flip: false, hop: 0, alt: false }
    if (hp === lap) { // terminou: convidado sai, anfitrião volta ao centro
      const c = b - lap / 2
      guest = { x: right + 2 * c, flip: false, hop: 0, alt: false }
      host = { x: Math.min(cx, c), flip: false, hop: 0, alt: false }
      if (host.x === cx && guest.x > W) return null
    }
  }
  if (kind === 'duel' && b >= 0) {
    if (b < 24) { // trocam golpes: cada um avança por vez, faísca no meio
      const k = Math.floor(b / 4)
      const lunge = b % 4 === 1 || b % 4 === 2 ? 3 : 0
      if (k % 2 === 0) host = { ...host, x: lunge, hop: b % 4 === 1 ? 2 : 0 }
      else guest = { ...guest, x: right - lunge, hop: b % 4 === 1 ? 2 : 0 }
      if (b % 4 === 2) clash = Math.floor((host.x + SPRITE_W + guest.x) / 2)
    } else {
      const c = b - 24
      guest = { x: right + 2 * c, flip: false, hop: 0, alt: false }
      host = { x: Math.min(cx, c), flip: false, hop: 0, alt: false }
      if (host.x === cx && guest.x > W) return null
    }
  }
  return { host, guest, clash, talk }
}

export function scene(n: number, seed0: number, names: string[], W: number, force?: Force): Scene {
  const turn = Math.floor(n / TURN)
  const t = n % TURN
  const seed = hash(turn * 31 + seed0)
  // 5 e o número de personagens são coprimos: percorre todos sem repetir em sequência
  const at = (k: number) => ((k * 5 + seed0) % names.length + names.length) % names.length
  const idx = at(turn)
  const right = Math.max(0, W - SPRITE_W)
  const cx = Math.floor(right / 2)
  let x = cx
  let flip = false
  let hop = 0
  let fx: Scene['fx'] = null
  let talk: Talk | null = null
  const encounter = (who: number, a: number, key: string, seedOut: number): Scene | null => {
    const p = partner(names[who]!)
    const m = p && meet(p.kind, a, cx, W)
    if (!p || !m) return null
    const tk: Talk | null = m.talk ? { kind: 'enc', since: m.talk.since, key: `${key}:enc${m.talk.line}`, who: m.talk.who, line: m.talk.line } : null
    return {
      turn, idx: who, seed: seedOut, x: m.host.x, flip: m.host.flip, hop: m.host.hop, fx: null, talk: tk, alt: m.host.alt,
      guest: { name: p.guest, ...m.guest }, clash: m.clash,
    }
  }
  if (force && n > force.at && n - force.at < 200) {
    const a = n - force.at - 1
    if (force.enc) {
      const e = encounter(force.idx, a, `f${force.at}`, 0)
      if (e) return e
    } else {
      // Kirby forçado engole quem estava no palco (ou o anterior, se era ele mesmo)
      const ft = Math.floor(force.at / TURN) // fixo pelo tick do pedido: não troca no meio se virar o turno
      const src = at(ft) === force.idx ? at(ft - 1) : at(ft)
      const mv = moves(names[force.idx]!, names[src]!)
      const r = act(mv.kinds, a, cx, W)
      if (r) {
        return {
          turn, idx: force.idx, seed: 0, x: r.m.x, flip: r.m.flip, hop: r.m.hop, fx: { kind: r.kind, t: r.t, power: force.power },
          talk: a < 10 ? { kind: 'shout', since: a, key: `f${force.at}:shout` } : null,
          alt: altOn(r.kind, r.t, r.m.dur), hat: r.part > 0 ? mv.hat : undefined,
        }
      }
    }
  }
  const plan = seed % 4 // 0 especial, 1 passeio, 2 pulinhos, 3 encontro (quem não tem par dá pulinhos)
  const a = t - ACT_AT
  let alt = false
  let hat: string | undefined
  if (plan === 3 && a >= 0) {
    const e = encounter(idx, a, `${turn}`, seed)
    if (e) return e
  }
  if (plan === 0 && a >= 0) {
    const mv = moves(names[idx]!, names[at(turn - 1)]!)
    const r = act(mv.kinds, a, cx, W)
    if (r) {
      fx = { kind: r.kind, t: r.t }
      ;({ x, hop, flip } = r.m)
      alt = altOn(r.kind, r.t, r.m.dur)
      if (r.part > 0) hat = mv.hat
      if (a < 10) talk = { kind: 'shout', since: a, key: `${turn}:shout` }
    }
  } else if (plan === 1 && a >= 0 && right >= 6) {
    // centro → esquerda → direita → centro
    if (a < cx) { x = cx - a - 1; flip = true }
    else if (a < cx + right) { x = a - cx + 1 }
    else if (a < 2 * right) { x = right - (a - cx - right) - 1; flip = true }
    x = Math.max(0, Math.min(right, x))
  } else if ((plan === 2 || plan === 3) && a >= 0 && a < 24) {
    hop = HOPS[a % 8] ?? 0
  }
  if (!talk && t >= HELLO[0] && t < HELLO[1]) talk = { kind: 'hello', since: t - HELLO[0], key: `${turn}:hello` }
  if (!talk && t >= CHAT[0] && t < CHAT[1]) talk = { kind: 'chat', since: t - CHAT[0], key: `${turn}:chat` }
  return { turn, idx, seed, x, flip, hop, fx, talk, alt, hat }
}

/** Madeline fica de cabelo azul depois do dash; Arthur perde a armadura no fim da lança. */
function altOn(kind: FxKind, t: number, dur: number) {
  return (kind === 'airdash' && t >= 3 && t < dur - 1) || (kind === 'lance' && t >= dur - 6)
}

function wrap(text: string, width: number): string[] {
  const out: string[] = []
  let line = ''
  for (const word of text.split(' ')) {
    const w = word.length > width ? word.slice(0, width - 1) + '…' : word
    if (!line) line = w
    else if (line.length + 1 + w.length <= width) line += ' ' + w
    else { out.push(line); line = w }
  }
  if (line) out.push(line)
  return out.slice(0, 3)
}

/**
 * Caixa de diálogo estilo RPG: nome na borda, texto surgindo letra a letra,
 * ▼ piscando quando termina e rabinho apontando para a cabeça (col `tail`).
 */
export function bubble(name: string, text: string, since: number, width: number, tail: number, blink: boolean) {
  const inner = width - 4
  const lines = wrap(text, inner)
  let budget = Math.max(0, since * 6) // 6 letras por tick
  const total = lines.join('').length
  const shown = lines.map(l => {
    const part = l.slice(0, budget)
    budget = Math.max(0, budget - l.length)
    return part
  })
  const done = shown.join('').length >= total
  const label = `─ ${name} `
  const top = '╭' + label + '─'.repeat(Math.max(0, width - 2 - label.length)) + '╮'
  const body = shown.map((l, i) => {
    const last = i === shown.length - 1
    const pad = inner - l.length
    const mark = last && done && blink ? '▼' : ' '
    return '│ ' + l + ' '.repeat(Math.max(0, pad - 1)) + (pad > 0 ? mark : '') + ' │'
  })
  const t = Math.min(Math.max(tail, 2), width - 4)
  const bottom = '╰' + '─'.repeat(t - 1) + '╮ ╭' + '─'.repeat(width - t - 4) + '╯'
  const stem = ' '.repeat(t + 1) + '╲'
  return { top, body, bottom, stem }
}

